For a brick at $(bx, by, bw, bh)$ and a ball at $P_{old}$ moving to $P_{new}$ with radius $r$:
The ball's swept volume is the area between two shifted AABBs (or a capsule).
A simpler way is to check if the segment $(P_{old}, P_{new})$ intersects the brick expanded by $r$.

Expanded brick: $bx-r \le x \le bx+bw+r$ and $by-r \le y \le by+bh+r$.

Intersection of segment $P_{old} + t(P_{new} - P_{old})$ where $t \in [0, 1]$ with the expanded brick.

This is a classic AABB intersection test.

```javascript
function intersectSegmentAABB(p0, p1, min, max) {
  let tMin = -Infinity, tMax = Infinity;
  const d = { x: p1.x - p0.x, y: p1.y - p0.y };

  // X axis
  if (d.x !== 0) {
    const tx1 = (min.x - p0.x) / d.x;
    const tx2 = (max.x - p0.x) / d.x;
    tMin = Math.max(tMin, Math.min(tx1, tx2));
    tMax = Math.min(tMax, Math.max(tx1, tx2));
  } else if (p0.x < min.x || p0.x > max.x) {
    return null;
  }

  // Y axis
  if (d.y !== 0) {
    const ty1 = (min.y - p0.y) / d.y;
    const ty2 = (max.y - p0.y) / d.y;
    tMin = Math.max(tMin, Math.min(ty1, ty2));
    tMax = Math.min(tMax, Math.max(ty1, ty2));
  } else if (p0.y < min.y || p0.y > max.y) {
    return null;
  }

  if (tMax >= tMin && tMax >= 0 && tMin <= 1) {
    return Math.max(0, tMin);
  }
  return null;
}
