```javascript
function resolveBrickCollision(state, brick) {
  const { ball } = state;
  const r = ball.r;
  const min = { x: brick.x - r, y: brick.y - r };
  const max = { x: brick.x + brick.w + r, y: brick.y + brick.h + r };

  // Tunneling / Sweep detection
  let t = 0;
  if (!collides(ball, brick)) {
    const p0 = { x: ball.prevX, y: ball.prevY };
    const p1 = { x: ball.x, y: ball.y };
    const hitT = intersectSegmentAABB(p0, p1, min, max);
    if (hitT === null) return false;
    t = hitT;
  }

  // Collision detected! (either now or during sweep)
  // Resolve face: smallest penetration
  const dx1 = (ball.x + r) - brick.x;      // dist from right edge of ball to left edge of brick
  const dx2 = (brick.x + brick.w) - (ball.x - r); // dist from right edge of brick to left edge of ball
  const dy1 = (ball.y + r) - brick.y;      // dist from bottom edge of ball to top edge of brick
  const dy2 = (brick.y + brick.h) - (ball.y - r); // dist from bottom edge of brick to top edge of ball

  const minX = Math.min(dx1, dx2);
  const minY = Math.min(dy1, dy2);

  if (minX < minY) {
    // Side hit
    ball.vx = (dx1 < dx2) ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    // Push out
    ball.x = (dx1 < dx2) ? brick.x - r : brick.x + brick.w + r;
  } else if (minY < minX) {
    // Top/Bottom hit
    ball.vy = (dy1 < dy2) ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    // Push out
    ball.y = (dy1 < dy2) ? brick.y - r : brick.y + brick.h + r;
